\usepackage{booktabs}

\title{Riverside Promenade Use and Self-Reported Mental
Wellbeing: A Repeated Cross-Sectional Study}
\author{C.~Vidal and R.~Okafor}
\date{May 2026}

\begin{document}
\maketitle

\begin{abstract}
Using three waves of a repeated cross-sectional survey around
a newly opened riverside promenade, we examine whether regular
promenade use is associated with self-reported mental
wellbeing, and whether the association differs by distance
from home to the riverfront.
\end{abstract}

\section{Introduction}
Urban blue space is increasingly treated as mental-health
infrastructure, but evaluations of specific waterfront
interventions remain thin. A 2.4 km riverside promenade opened
in phases between 2023 and 2025, giving us a natural setting
to study use and wellbeing in nearby neighbourhoods.

\input{sections/findings}

\section{Discussion}
Regular promenade use tracks higher wellbeing scores, with the
steepest gradient among residents within a fifteen-minute
walk. Because the design is cross-sectional, we read the
estimates as associations and discuss selection into use as
the main threat.

\section{Conclusion}
Promenade use is associated with higher self-reported
wellbeing among nearby residents. Longitudinal follow-up is
planned to separate selection from any causal effect.
\end{document}

